// Build the OpenRouter chat/completions payload for the plan curator.
// The prompt lives here (plain JS) rather than inside the HTTP node's JSON body so
// quotes, apostrophes and the request-JSON interpolation need no double escaping —
// and this removes the old expression-mode footgun (a 'Fixed' prompt field used to
// send the literal {{ }} placeholder and silently no-curation every plan).
//
// ⚠ Verify the slug at https://openrouter.ai/models — OpenRouter slugs are
// `vendor/model` and do change. Latency is the binding constraint: /api/curate-plan
// aborts at 15s (N8N_TIMEOUT_MS) and then silently persists the pure rule-engine
// plan, so a slow model shows up as a permanently missing 'Why this plan' card, not
// as an error. Verified live 2026-07-09: a sonnet-class model took ~17s on a real
// ~40-plant menu and fell back every time; a haiku-class model answers in seconds.
const MODEL = 'anthropic/claude-haiku-4.5';

const body = $('Webhook').item.json.body || {};

// Contract source of truth: src/lib/plan-curation.ts (CURATION_INTRO_MAX / CURATION_WHY_MAX,
// selectionBounds) + src/app/api/curate-plan/route.ts.
const PROMPT = [
  "You are Sproutly's planting-plan curator for gardens in Germany. You receive a SITE (its real, measured conditions) and a MENU of plants that already passed hard survival filters (sun, winter hardiness, physical fit) for that site. Your job: choose the best-composed mix from the MENU ONLY, and explain it in warm, concrete, evidence-forward English.",
  '',
  'Rules:',
  '- Pick between bounds.min_picks and bounds.max_picks plants. Use each plant at most once. Use ONLY ids from the menu — never invent an id.',
  "- Compose like a planting designer: favour layered structure (taller anchors + perennials + groundcover when available), native species, and plants matching the site's soil, moisture and the user's maintenance preference.",
  "- Write an intro of 2–3 sentences (max limits.intro_max_chars characters) explaining why this COMBINATION suits this specific site — reference its actual conditions (sun, surface, soil, size). Qualitative effort statements are welcome (e.g. 'every pick here is low-maintenance'); NEVER invent numbers (no 'X minutes per month'), never moralize about climate, guilt, or duty.",
  "- For EACH picked plant write one 'why' line (max limits.why_max_chars characters): concrete and specific to this site or this plant's role in the mix — maintenance effort, watering, structure, wildlife value. No fluff, no guilt.",
  '- Output ONLY one minified JSON object, no markdown, no prose: {"intro":"...","selection":[{"plant_id":"<id from the menu>","why":"..."}]}',
  '',
  'Here is the request JSON (site, bounds, limits, plants menu):',
  JSON.stringify(body),
].join('\n');

return [
  {
    json: {
      payload: {
        model: MODEL,
        // intro + up to 12 why-lines fit comfortably.
        max_tokens: 2000,
        messages: [{ role: 'user', content: PROMPT }],
      },
    },
  },
];

// Parse the model's JSON answer and re-validate it against the REQUEST the app sent.
// The app re-validates again (route + client), but rejecting garbage here keeps
// the failure visible in n8n executions. Contract: docs/n8n-plan-curation-workflow.md
const body = $('Webhook').item.json.body || {};
const menu = new Set((body.plants || []).map((p) => p.id));
const bounds = body.bounds || { min_picks: 1, max_picks: 12 };
const limits = body.limits || { intro_max_chars: 600, why_max_chars: 200 };

// Provider-agnostic reply extraction: OpenRouter / OpenAI-compatible
// (`choices[0].message.content`, the current wiring) first, then the Anthropic /
// n8n AI node shapes, so switching the upstream node back does not break this one.
// NOTE: an unrecognised shape leaves text '' -> JSON.parse fails -> no_curation,
// which the app absorbs SILENTLY (plan renders with no rationale, no error). If you
// add a provider, add its branch here first.
const item = $input.first().json;
let text = item.choices?.[0]?.message?.content ?? item.text ?? item.content ?? item.message ?? '';
if (Array.isArray(text)) text = text[0]?.text ?? '';
if (typeof text === 'object' && text !== null) text = text.text ?? JSON.stringify(text);

function fail(message) {
  return [{ json: { branch: 'fallback', status: 'no_curation', message } }];
}

let parsed;
try {
  // Tolerate accidental markdown fences.
  const raw = String(text).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  return fail('Model answer was not valid JSON');
}

const intro = typeof parsed.intro === 'string' ? parsed.intro.trim() : '';
const selection = Array.isArray(parsed.selection) ? parsed.selection : null;
if (!intro || intro.length > limits.intro_max_chars) return fail('intro missing or too long');
if (!selection || selection.length < bounds.min_picks || selection.length > bounds.max_picks) {
  return fail('selection count outside bounds');
}
const seen = new Set();
const shaped = [];
for (const pick of selection) {
  const id = pick && typeof pick.plant_id === 'string' ? pick.plant_id : null;
  const why = pick && typeof pick.why === 'string' ? pick.why.trim() : '';
  if (!id || !menu.has(id) || seen.has(id)) return fail('selection contains an invalid or duplicate id');
  if (!why || why.length > limits.why_max_chars) return fail('a why line is missing or too long');
  seen.add(id);
  shaped.push({ plant_id: id, why });
}

return [{ json: { branch: 'ok', status: 'ok', intro, selection: shaped } }];
